1645	    isort: &isort::settings::Settings,
1646	    flake8_import_conventions: &flake8_import_conventions::settings::Settings,
1647	) -> Result<()> {
1648	    use std::fmt::Write;
1649	    let mut err_body = String::new();
1650	    for required_import in &isort.required_imports {
1651	        // Ex: `from foo import bar as baz` OR `import foo.bar as baz`
1652	        // - qualified name: `foo.bar`
1653	        // - bound name: `baz`
1654	        // - conflicts with: `{"foo.bar":"buzz"}`
1655	        // - does not conflict with either of
1656	        //   - `{"bar":"buzz"}`
1657	        //   - `{"foo.bar":"baz"}`
1658	        let qualified_name = required_import.qualified_name().to_string();
1659	        let bound_name = required_import.bound_name();
1660	        let Some(alias) = flake8_import_conventions.aliases.get(&qualified_name) else {
1661	            continue;
1662	        };
1663	        if alias != bound_name {
1664	            writeln!(err_body, "    - `{qualified_name}` -> `{alias}`").unwrap();
1665	        }
1666	    }
1667	
1668	    if !err_body.is_empty() {
1669	        return Err(anyhow!(
1670	            "Required import specified in `lint.isort.required-imports` (I002) \
1671	            conflicts with the required import alias specified in either \
1672	            `lint.flake8-import-conventions.aliases` or \
1673	            `lint.flake8-import-conventions.extend-aliases` (ICN001):\
1674	                \n{err_body}\n\
1675	            Help: Remove the required import or alias from your configuration."
1676	        ));
1677	    }
1678	
1679	    Ok(())
1680	}
