/// Detect conflicts between I002 (missing-required-import) and PYI025
/// (unaliased-collections-abc-set-import).
///
/// PYI025 requires `Set` from `collections.abc` to be imported under the alias `AbstractSet`, so a
/// required import of `from collections.abc import Set` that is not aliased as `AbstractSet` can
/// never be satisfied while PYI025 is enabled.
fn conflicting_required_import_pyi025(
    isort: &isort::settings::Settings,
    rules: &RuleTable,
) -> Result<()> {
    if !rules.enabled(Rule::UnaliasedCollectionsAbcSetImport) {
        return Ok(());
    }

    for required_import in &isort.required_imports {
        if required_import.qualified_name().to_string() == "collections.abc.Set"
            && required_import.bound_name() != "AbstractSet"
